    """
    Check if field named `field_name` in model `model` exists and is a
    valid content_type field (is a ForeignKey to ContentType).
    """
    try:
        field = self.model._meta.get_field(self.ct_field)
    except FieldDoesNotExist:
        return [
            checks.Error(
