            return [
                checks.Error(
                    "'%s.%s' is not a ForeignKey."
                    % (self.model._meta.object_name, self.ct_field),
                    hint=(
                        "GenericForeignKeys must use a ForeignKey to "
                        "'contenttypes.ContentType' as the 'content_type' field."
                    ),
                    obj=self,
