def _message_post_after_hook(self, message, msg_vals):
    """
    This method is called just before _notify_thread() method which is calling the _to_store()
    method. We need a 'chatbot.message' record before it happens to correctly display the message.
    It's created only if the mail channel is linked to a chatbot step. We also need to save the
    user answer if the current step is a question selection.
    """
    if self.chatbot_current_step_id:
        selected_answer = (
            self.env["chatbot.script.answer"]
            .browse(self.env.context.get("selected_answer_id"))
            .exists()
        )
        if selected_answer in self.chatbot_current_step_id.answer_ids:
            # sudo - chatbot.message: finding the question message to update the user answer is allowed.
            question_msg = (
                self.env["chatbot.message"]
                .sudo()
                .search(
                    [
                        ("discuss_channel_id", "=", self.id),
                        ("script_step_id", "=", self.chatbot_current_step_id.id),
                    ],
                    order="id DESC",
                    limit=1,
                )
            )
            question_msg.user_script_answer_id = selected_answer
            question_msg.user_raw_script_answer_id = selected_answer.id
            if store := self.env.context.get("message_post_store"):
                store.add(message, for_current_user=True).add(question_msg.mail_message_id)
            partner, guest = self.env["res.partner"]._get_current_persona()
            (partner or guest)._bus_send_store(
                Store().add_model_values(
                    "ChatbotStep",
                    {
                        "id": (self.chatbot_current_step_id.id, question_msg.mail_message_id.id),
                        "scriptStep": self.chatbot_current_step_id.id,
                        "message": question_msg.mail_message_id.id,
                        "selectedAnswer": selected_answer.id,
                    },
                )
            )

        self.env["chatbot.message"].sudo().create(
            {
                "mail_message_id": message.id,
                "discuss_channel_id": self.id,
                "script_step_id": self.chatbot_current_step_id.id,
            }
        )

    if (
        # sudo: discuss.channel - visitor can access channel member history
        self.livechat_active and self.sudo().livechat_channel_member_history_ids.filtered(
            lambda h: h.partner_id == message.author_id and h.livechat_member_type == "agent"
        )
    ):
        self.livechat_failure = "no_failure"

    return super()._message_post_after_hook(message, msg_vals)

def write(self, vals):
    if not vals:
        return True
    protected_fields = self._get_lock_date_protected_fields()
    account_to_write = self.env['account.account'].browse(vals['account_id']) if 'account_id' in vals else None

    # Check writing a deprecated account.
    if account_to_write and account_to_write.deprecated:
        raise UserError(_('You cannot use a deprecated account.'))

    inalterable_fields = set(self._get_integrity_hash_fields()).union({'inalterable_hash', 'secure_sequence_number'})
    hashed_moves = self.move_id.filtered('inalterable_hash')
    violated_fields = set(vals) & inalterable_fields
    if hashed_moves and violated_fields:
        raise UserError(_(
            "You cannot edit the following fields: %s.\n"
            "The following entries are already hashed:\n%s",
            ', '.join(f['string'] for f in self.fields_get(violated_fields).values()),
            '\n'.join(hashed_moves.mapped('name')),
        ))

    line_to_write = self
    vals = self._sanitize_vals(vals)
    for line in self:
        if not any(self.env['account.move']._field_will_change(line, vals, field_name) for field_name in vals):
            line_to_write -= line
            continue

        if line.parent_state == 'posted' and any(self.env['account.move']._field_will_change(line, vals, field_name) for field_name in ('tax_ids', 'tax_line_id')):
            raise UserError(_('You cannot modify the taxes related to a posted journal item, you should reset the journal entry to draft to do so.'))

        # Check the lock date.
        if line.parent_state == 'posted' and any(self.env['account.move']._field_will_change(line, vals, field_name) for field_name in protected_fields['fiscal']):
            line.move_id._check_fiscalyear_lock_date()

        # Check the tax lock date.
        if line.parent_state == 'posted' and any(self.env['account.move']._field_will_change(line, vals, field_name) for field_name in protected_fields['tax']):
            line._check_tax_lock_date()

        # Check the reconciliation.
        if any(self.env['account.move']._field_will_change(line, vals, field_name) for field_name in protected_fields['reconciliation']):
            line._check_reconciliation()

    move_container = {'records': self.move_id}
    with self.move_id._check_balanced(move_container),\
         self.env.protecting(self.env['account.move']._get_protected_vals(vals, self)),\
         self.move_id._sync_dynamic_lines(move_container),\
         self._sync_invoice({'records': self}):
        self = line_to_write
        if not self:
            return True
        # Tracking stuff can be skipped for perfs using tracking_disable context key
        if not self.env.context.get('tracking_disable', False):
            # Get all tracked fields (without related fields because these fields must be manage on their own model)
            tracking_fields = []
            for value in vals:
                field = self._fields[value]
                if hasattr(field, 'related') and field.related:
                    continue # We don't want to track related field.
                if hasattr(field, 'tracking') and field.tracking:
                    tracking_fields.append(value)
            ref_fields = self.env['account.move.line'].fields_get(tracking_fields)

            # Get initial values for each line
            move_initial_values = {}
            for line in self.filtered(lambda l: l.move_id.posted_before): # Only lines with posted once move.
                for field in tracking_fields:
                    # Group initial values by move_id
                    if line.move_id.id not in move_initial_values:
                        move_initial_values[line.move_id.id] = {}
                    move_initial_values[line.move_id.id].update({field: line[field]})

        result = super().write(vals)
        self.move_id._synchronize_business_models(['line_ids'])
        if any(field in vals for field in ['account_id', 'currency_id']):
            self._check_constrains_account_id_journal_id()

        if not self.env.context.get('tracking_disable', False):
            # Log changes to move lines on each move
            for move_id, modified_lines in move_initial_values.items():
                for line in self.filtered(lambda l: l.move_id.id == move_id):
                    tracking_value_ids = line._mail_track(ref_fields, modified_lines)[1]
                    if tracking_value_ids:
                        msg = _("Journal Item %s updated", line._get_html_link(title=f"#{line.id}"))
                        line.move_id._message_log(
                            body=msg,
                            tracking_value_ids=tracking_value_ids
                        )

    return result

