        version = self.env['hr.version'].search(
            [('employee_id', 'in', employee.ids), ('date_version', '<=', fields.Date.today())],
            order='date_version desc',
            limit=1,
        )
        if version:
            employee.current_version_id = version
        elif employee.version_ids:
            employee.current_version_id = employee.version_ids[0]
        else:
            employee.current_version_id = False

def _get_attendance_intervals(self, start_dt, end_dt):
    assert start_dt.tzinfo and end_dt.tzinfo, "function expects localized date"
    # {resource: intervals}
    employees_by_calendar = defaultdict(lambda: self.env['hr.employee'])
    for version in self:
        if version.work_entry_source != 'calendar':
            continue
        employees_by_calendar[version.resource_calendar_id] |= version.employee_id
    result = dict()
    for calendar, employees in employees_by_calendar.items():
        result.update(calendar._attendance_intervals_batch(
            start_dt,
            end_dt,
            resources=employees.resource_id,
            tz=pytz.timezone(calendar.tz) if calendar.tz else pytz.utc
        ))
    return result

