def do_down(self, arg):
    """d(own) [count]
    Move the current frame count (default one) levels down in the
    stack trace (to a newer frame).

    Will skip hidden frames.
    """
    if self.curindex + 1 == len(self.stack):
        self.error("Newest frame")
        return
    try:
        count = int(arg or 1)
    except ValueError:
        self.error("Invalid frame count (%s)" % arg)
        return
    if count < 0:
        _newframe = len(self.stack) - 1
    else:
        counter = 0
        skipped = 0
        hidden_frames = self.hidden_frames(self.stack)
        for i in range(self.curindex + 1, len(self.stack)):
            if hidden_frames[i] and self.skip_hidden:
                skipped += 1
                continue
            counter += 1
            if counter >= count:
                break
        else:
            self.error(
                "all frames below hidden, use `skip_hidden False` to get get into those."
            )
            return

        if skipped:
            print(
                self.theme.format(
                    [
                        (
                            Token.ExcName,
                            f"    [... skipped {skipped} hidden frame(s)]",
                        ),
                        (Token, "\n"),
                    ]
                )
            )
        _newframe = i

    self._select_frame(_newframe)

def notebook(self, s):
    """Export and convert IPython notebooks.

    This function can export the current IPython history to a notebook file.
    For example, to export the history to "foo.ipynb" do "%notebook foo.ipynb".
    """
    args = magic_arguments.parse_argstring(self.notebook, s)
    outfname = os.path.expanduser(args.filename)

    from nbformat import write, v4

    cells = []
    hist = list(self.shell.history_manager.get_range())
    outputs = self.shell.history_manager.outputs
    exceptions = self.shell.history_manager.exceptions

    if(len(hist)<=1):
        raise ValueError('History is empty, cannot export')
    for session, execution_count, source in hist[:-1]:
        cell = v4.new_code_cell(execution_count=execution_count, source=source)
        for output in outputs[execution_count]:
            for mime_type, data in output.bundle.items():
                if output.output_type == "out_stream":
                    text = data if isinstance(data, list) else [data]
                    cell.outputs.append(v4.new_output("stream", text=text))
                elif output.output_type == "err_stream":
                    text = data if isinstance(data, list) else [data]
                    err_output = v4.new_output("stream", text=text)
                    err_output.name = "stderr"
                    cell.outputs.append(err_output)
                elif output.output_type == "execute_result":
                    cell.outputs.append(
                        v4.new_output(
                            "execute_result",
                            data={mime_type: data},
                            execution_count=execution_count,
                        )
                    )
                elif output.output_type == "display_data":
                    cell.outputs.append(
                        v4.new_output(
                            "display_data",
                            data={mime_type: data},
                        )
                    )
                else:
                    raise ValueError(f"Unknown output type: {output.output_type}")

        # Check if this execution_count is in exceptions (current session)
        if execution_count in exceptions:
            cell.outputs.append(
                v4.new_output("error", **exceptions[execution_count])
            )
