                data, salt.utils.event.tagify([jid, "ret", host], "job")
            )
    if self.event is not None:
        self.event.destroy()
    if self.opts.get("static"):
        salt.output.display_output(sret, outputter, self.opts)
    if final_exit:
        sys.exit(salt.defaults.exitcodes.EX_AGGREGATE)

