            db_shape["points"] = []

        if db_shape.parent is None:
            db_shape.elements = []
            shapes[db_shape.id] = db_shape
        else:
            if db_shape.parent not in elements:
                elements[db_shape.parent] = []
            elements[db_shape.parent].append(db_shape)

    for shape_id, shape_elements in elements.items():
