    fjacd_perms = [(q, m, n)]
    fjacb_perms = [(q, p, n)]

    if q == 1:
        fcn_perms.append((n,))
        fjacd_perms.append((m, n))
        fjacb_perms.append((p, n))
    if m == 1:
        fjacd_perms.append((q, n))
    if p == 1:
