                recent_rc.append((rc, sub_slot_total_iters))
                sub_slot_total_iters = uint128(sub_slot_total_iters - curr.sub_slot_iters)
        curr = self.try_block_record(curr.prev_hash)
    return list(reversed(recent_rc))

