def validate_dtype(cls, v: Any) -> TorchIntDType | None:
    if v == "int4":
        return TorchIntDType.int4
    if v == "int8":
        return TorchIntDType.int8
    raise ValueError(f"Invalid dtype: '{v}'. Must be one of: ['int4', 'int8']")

