def to_base32(number):
    is_neg: bool = number < 0
    if is_neg:
        number = -number

    digits = bytearray()
    while number:
        digit: cython.uint = number & 31
        digit_char: cython.char = b'0123456789abcdefghijklmnopqrstuv'[digit]
        digits.append(digit_char)
        number >>= 5
    if not digits:
        return b'0'

    if is_neg:
        digits.append(ord(b'-'))
    digits.reverse()
    return digits

