def analyse_types(self, env, use_temp=0):
    from . import ExprNodes

    self.rhs = self.rhs.analyse_types(env)

    unrolled_assignment = self.unroll_rhs(env)
    if unrolled_assignment:
        return unrolled_assignment

    self.lhs = self.lhs.analyse_target_types(env)
    self.lhs.gil_assignment_check(env)
    unrolled_assignment = self.unroll_lhs(env)
    if unrolled_assignment:
        return unrolled_assignment

    if isinstance(self.lhs, ExprNodes.MemoryViewIndexNode):
        self.lhs.analyse_broadcast_operation(self.rhs)
        self.lhs = self.lhs.analyse_as_memview_scalar_assignment(self.rhs)
    elif self.lhs.type.is_array:
        if not isinstance(self.lhs, ExprNodes.SliceIndexNode):
            # cannot assign to C array, only to its full slice
            lhs = ExprNodes.SliceIndexNode(self.lhs.pos, base=self.lhs, start=None, stop=None)
            self.lhs = lhs.analyse_target_types(env)

    if self.lhs.type.is_cpp_class:
        op = env.lookup_operator_for_types(self.pos, '=', [self.lhs.type, self.rhs.type])
        if op:
            rhs = self.rhs
            self.is_overloaded_assignment = True
            self.exception_check = op.type.exception_check
            self.exception_value = op.type.exception_value
            if self.exception_check == '+' and self.exception_value is None:
                env.use_utility_code(UtilityCode.load_cached("CppExceptionConversion", "CppSupport.cpp"))
        else:
            rhs = self.rhs.coerce_to(self.lhs.type, env)
    else:
        rhs = self.rhs.coerce_to(self.lhs.type, env)

    if use_temp or rhs.is_attribute or (
            not rhs.is_name and not rhs.is_literal and
            rhs.type.is_pyobject):
        # things like (cdef) attribute access are not safe (traverses pointers)
        rhs = rhs.coerce_to_temp(env)
    elif rhs.type.is_pyobject:
        rhs = rhs.coerce_to_simple(env)
    self.rhs = rhs
    return self

def slot_code(self, scope):
    if not scope.needs_gc():
        return "0"
    if not scope.has_cyclic_pyobject_attrs:
        # if the type does not have GC relevant object attributes, it can
        # delegate GC methods to its parent - iff the parent functions
        # are defined in the same module
        parent_type_scope = scope.parent_type.base_type.scope
        if scope.parent_scope is parent_type_scope.parent_scope:
            entry = scope.parent_scope.lookup_here(scope.parent_type.base_type.name)
            if entry.visibility != 'extern':
                return self.slot_code(parent_type_scope)
    return InternalMethodSlot.slot_code(self, scope)

def slot_code(self, scope):
    if not self._needs_own(scope):
        # if the type does not have object attributes, it can
        # delegate GC methods to its parent - iff the parent
        # functions are defined in the same module
        slot_code = self._parent_slot_function(scope)
        return slot_code or '0'
    return InternalMethodSlot.slot_code(self, scope)

def p_from_import_statement(s: PyrexScanner, first_statement: cython.bint = 0):
    # s.sy == 'from'
    pos = s.position()
    s.next()
    if s.sy in ('.', '...'):
        # count relative import level
        level = 0
        while s.sy in ('.', '...'):
            level += len(s.sy)
            s.next()
    else:
        level = None
    if level is not None and s.sy in ('import', 'cimport'):
        # we are dealing with "from .. import foo, bar"
        dotted_name_pos, dotted_name = s.position(), s.context.intern_ustring('')
    else:
        if level is None and Future.absolute_import in s.context.future_directives:
            level = 0
        (dotted_name_pos, _, dotted_name, _) = p_dotted_name(s, as_allowed=False)
    if s.sy not in ('import', 'cimport'):
        s.error("Expected 'import' or 'cimport'")
    kind = s.sy
    s.next()

    is_cimport = kind == 'cimport'
    is_parenthesized = False
    if s.sy == '*':
        imported_names = [(s.position(), s.context.intern_ustring("*"), None)]
        s.next()
    else:
        if s.sy == '(':
            is_parenthesized = True
            s.next()
        imported_names = [p_imported_name(s)]
    while s.sy == ',':
        s.next()
        if is_parenthesized and s.sy == ')':
            break
        imported_names.append(p_imported_name(s))
    if is_parenthesized:
        s.expect(')')
    if dotted_name == '__future__':
        if not first_statement:
            s.error("from __future__ imports must occur at the beginning of the file")
        elif level:
            s.error("invalid syntax")
        else:
            for (name_pos, name, as_name) in imported_names:
                if name == "braces":
                    s.error("not a chance", name_pos)
                    break
                try:
                    directive = getattr(Future, name)
                except AttributeError:
                    s.error("future feature %s is not defined" % name, name_pos)
                    break
                s.context.future_directives.add(directive)
        return Nodes.PassStatNode(pos)
    elif is_cimport:
        return Nodes.FromCImportStatNode(
            pos, module_name=dotted_name,
            relative_level=level,
            imported_names=imported_names)
    else:
        imported_name_strings = []
        items = []
        for (name_pos, name, as_name) in imported_names:
            imported_name_strings.append(
                ExprNodes.IdentifierStringNode(name_pos, value=name))
            items.append(
                (name, ExprNodes.NameNode(name_pos, name=as_name or name)))
        import_list = ExprNodes.ListNode(
            imported_names[0][0], args=imported_name_strings)
        return Nodes.FromImportStatNode(pos,
            module = ExprNodes.ImportNode(dotted_name_pos,
                module_name = ExprNodes.IdentifierStringNode(pos, value = dotted_name),
                is_import_as_name = False,
                level = level,
                name_list = import_list),
            items = items)


@cython.cfunc

def tentatively_scan(scanner: PyrexScanner):
    errors = hold_errors()
    try:
        put_back_on_failure = scanner.put_back_on_failure
        scanner.put_back_on_failure = []
        initial_state = (scanner.sy, scanner.systring, scanner.position())
        try:
            yield errors
        except CompileError as e:
            pass
        finally:
            if errors:
                if scanner.put_back_on_failure:
                    for put_back in reversed(scanner.put_back_on_failure[:-1]):
                        scanner.put_back(*put_back)
                    # we need to restore the initial state too
                    scanner.put_back(*initial_state)
            elif put_back_on_failure is not None:
                # the outer "tentatively_scan" block that we're in might still
                # want to undo this block
                put_back_on_failure.extend(scanner.put_back_on_failure)
            scanner.put_back_on_failure = put_back_on_failure
    finally:
        release_errors(ignore=True)

def next(self):
    try:
        sy, systring = self.read()
    except UnrecognizedInput:
        self.error_at_scanpos("Unrecognized character")
        return  # just a marker, error() always raises
    if sy == IDENT:
        if systring in self.keywords:
            if systring == 'print' and print_function in self.context.future_directives:
                self.keywords.pop('print', None)
            elif systring == 'exec' and self.context.language_level >= 3:
                self.keywords.pop('exec', None)
            else:
                sy = self.keywords[systring]  # intern
        systring = self.context.intern_ustring(systring)
    if self.put_back_on_failure is not None:
        self.put_back_on_failure.append((sy, systring, self.position()))
    self.sy = sy
    self.systring = systring
    if False:  # debug_scanner:
        _, line, col = self.position()
        if not self.systring or self.sy == self.systring:
            t = self.sy
        else:
            t = "%s %s" % (self.sy, self.systring)
        print("--- %3d %2d %s" % (line, col, t))

