def _predict_proba(self, fh, X=None, marginal=True):
    """Combine full distribution forecasts from base & residual models."""
    if not _check_soft_dependencies("skpro", severity="none"):
        from sktime.utils.warnings import warn

        warn(
            "ResidualBoostingForecaster.predict_proba: optional "
            "dependency 'skpro' not found. "
            "Falling back to the default normal approximation via BaseForecaster. "
            "Install 'skpro' to enable exact shifted-distribution composition.",
            category=UserWarning,
            obj=self,
        )
        return super()._predict_proba(fh=fh, X=X, marginal=marginal)

    from skpro.distributions import MeanScale

    y_base = self.base_future_.predict(fh=fh, X=X)
    p_res = self.residual_forecaster_.predict_proba(fh=fh, X=X, marginal=marginal)

    return MeanScale(
        d=p_res, mu=y_base, sigma=1, index=p_res.index, columns=p_res.columns
    )

@classmethod

def assign_prs(prs, categs: list[dict[str, list[str]]]):
    """Assign PR to categories based on labels."""
    assigned = defaultdict(list)
    # Track module tags for each PR
    pr_modules = {}

    # Track additional credited users for contributors list
    additional_users = set()

    for i, pr in enumerate(prs):
        pr_labels = [label["name"] for label in pr["labels"]]

        # Assign to main categories
        for cat in categs:
            if not set(cat["labels"]).isdisjoint(set(pr_labels)):
                assigned[cat["title"]].append(i)

        # Track module tags for each PR
        for label in pr_labels:
            if label.startswith("module:"):
                module_name = label.replace("module:", "")
                # Fix for "base-framework" tag and benchmarking tag
                if module_name == "base-framework":
                    module_name = "base"
                pr_modules[i] = module_name

        # Check for additional users in PR title
        title = pr["title"]
        if title.startswith("&"):
            parts = title.split(" ", 1)
            user_part = parts[0].strip()
            username = user_part[1:]
            additional_users.add(username)

    # Assign unmatched PRs to "Other" category
    assigned["Other"] = list(
        set(range(len(prs))) - {i for _, j in assigned.items() for i in j}
    )

    return assigned, pr_modules, additional_users

