def amend_exploded_column_table(expression: exp.Expression) -> exp.Expression:
    # We check for expression.type because the columns can be amended only if types were inferred
    if isinstance(expression, exp.Select) and expression.type:
        for lateral in expression.args.get("laterals") or []:
            alias = lateral.args.get("alias")
            if (
                not isinstance(lateral.this, exp.Explode)
                or not isinstance(alias, exp.TableAlias)
                or len(alias.columns) != 1
            ):
                continue

            new_table = alias.this
            old_table = alias.columns[0].name.lower()

            # When transpiling a LATERAL VIEW EXPLODE Spark query, the exploded fields may be qualified
            # with the struct column, resulting in invalid Presto references that need to be amended
            for column in find_all_in_scope(expression, exp.Column):
                if column.db.lower() == old_table:
                    column.set("table", column.args["db"].pop())
                elif column.table.lower() == old_table:
                    column.set("table", new_table.copy())
                elif column.name.lower() == old_table and isinstance(column.parent, exp.Dot):
                    column.parent.replace(exp.column(column.parent.expression, table=new_table))

    return expression

def _parse_show_snowflake(self, this: str) -> exp.Show:
    scope = None
    scope_kind = None

    # will identity SHOW TERSE SCHEMAS but not SHOW TERSE PRIMARY KEYS
    # which is syntactically valid but has no effect on the output
    terse = self._tokens[self._index - 2].text.upper() == "TERSE"

    history = self._match_text_seq("HISTORY")

    like = self._parse_string() if self._match(TokenType.LIKE) else None

    if self._match(TokenType.IN):
        if self._match_text_seq("ACCOUNT"):
            scope_kind = "ACCOUNT"
        elif self._match_text_seq("CLASS"):
            scope_kind = "CLASS"
            scope = self._parse_table_parts()
        elif self._match_text_seq("APPLICATION"):
            scope_kind = "APPLICATION"
            if self._match_text_seq("PACKAGE"):
                scope_kind += " PACKAGE"
            scope = self._parse_table_parts()
        elif self._match_set(self.DB_CREATABLES):
            scope_kind = self._prev.text.upper()
            if self._curr:
                scope = self._parse_table_parts()
        elif self._curr:
            scope_kind = "SCHEMA" if this in self.SCHEMA_KINDS else "TABLE"
            scope = self._parse_table_parts()

    return self.expression(
        exp.Show,
        **{
            "terse": terse,
            "this": this,
            "history": history,
            "like": like,
            "scope": scope,
            "scope_kind": scope_kind,
            "starts_with": self._match_text_seq("STARTS", "WITH") and self._parse_string(),
            "limit": self._parse_limit(),
            "from": self._parse_string() if self._match(TokenType.FROM) else None,
            "privileges": self._match_text_seq("WITH", "PRIVILEGES")
            and self._parse_csv(lambda: self._parse_var(any_token=True, upper=True)),
        },
    )

