                        for v in reversed(vs):
                            stack.append((v, i, k, True))
                    elif vs is not None:
                        stack.append((vs, i, k, False))
        elif type(node) is exp.DataType.Type:
            payload[CLASS] = DATA_TYPE
            payload[VALUE] = node.value
