def redirect_clean_url_to_html(self, filename, path, language=None, version_slug=None):
    log.debug("Redirecting...", redirect=self)
    suffixes = ["/", "/index.html"]
    for suffix in suffixes:
        if filename.endswith(suffix):
            to = filename[: -len(suffix)]
            if not to:
                to = "index.html"
            else:
                to += ".html"
            return self.get_full_path(
                filename=to,
                language=language,
                version_slug=version_slug,
                allow_crossdomain=False,
            )

def checkout_revision(self, revision):
    try:
        code, out, err = self.run('git', 'checkout', '--force', revision)
        return [code, out, err]
    except RepositoryError as exc:
        raise RepositoryError(
            RepositoryError.FAILED_TO_CHECKOUT.format(revision),
        ) from exc

